void mutate_kex_algorithms(ssh_packet_t *pkts, size_t n)
{
    if (!pkts)
        return;
    uint32_t seed = 0x11111111u;
    for (size_t i = 0; i < n; ++i)
    {
        ssh_kexinit_t *k = kexinit_of(&pkts[i]);
        if (!k)
            continue;
        seed = mix_u32(seed + (uint32_t)i + k->kex_algorithms_len);
        if (k->kex_algorithms_len == 0 && (seed & 1u))
            set_default_kex_algs(k);
        namelist_mutate(k->kex_algorithms, &k->kex_algorithms_len, seed);
    }
}
void mutate_kex_algorithms_len(ssh_packet_t *pkts, size_t n)
{
    if (!pkts)
        return;
    uint32_t seed = 0x22222222u;
    for (size_t i = 0; i < n; ++i)
    {
        ssh_kexinit_t *k = kexinit_of(&pkts[i]);
        if (!k)
            continue;
        seed = mix_u32(seed + (uint32_t)i + k->kex_algorithms_len);
        uint32_t L = k->kex_algorithms_len;
        switch (seed & 3u)
        {
        case 0:
            L = 0;
            break;
        case 1:
            L = clamp_namelist(L + 3);
            break;
        case 2:
            L = SSH_MAX_NAMELIST_BYTES;
            break;
        default:
            L ^= 7u;
            break;
        }
        if (L > k->kex_algorithms_len)
        {
            while (k->kex_algorithms_len < L)
                k->kex_algorithms[k->kex_algorithms_len++] = 'a';
        }
        else
        {
            k->kex_algorithms_len = L;
        }
    }
}

