// first_kex_packet_follows (boolean/byte)
void mutate_first_kex_packet_follows(ssh_packet_t *pkts, size_t n)
{
    if (!pkts)
        return;
    uint32_t seed = 0xF00F00F0u;
    for (size_t i = 0; i < n; ++i)
    {
        ssh_kexinit_t *k = kexinit_of(&pkts[i]);
        if (!k)
            continue;
        seed = mix_u32(seed + (uint32_t)i + k->first_kex_packet_follows);
        switch (seed & 7u)
        {
        case 0:
            k->first_kex_packet_follows = 0;
            break;
        case 1:
            k->first_kex_packet_follows = 1;
            break;
        case 2:
            k->first_kex_packet_follows ^= 1;
            break;
        case 3:
            k->first_kex_packet_follows = (uint8_t)(seed & 1u);
            break;
        case 4:
            k->first_kex_packet_follows = 0xFF;
            break;
        default:
            k->first_kex_packet_follows = (uint8_t)((k->first_kex_packet_follows << 1) | 1u);
            break;
        }
    }
}


static uint8_t ssh_default_code_for_type(ssh_packet_type_t type)
{
    switch (type)
    {
    case SSH_DISCONNECT: return SSH_MSG_DISCONNECT;
    case SSH_IGNORE: return SSH_MSG_IGNORE;
    case SSH_UNIMPLEMENTED: return SSH_MSG_UNIMPLEMENTED;
    case SSH_DEBUG: return SSH_MSG_DEBUG;
    case SSH_SERVICE_ACCEPT: return SSH_MSG_SERVICE_ACCEPT;
    case SSH_KEXDH_REPLY: return SSH_MSG_KEXDH_REPLY;
    case SSH_KEX_DH_GEX_INIT: return SSH_MSG_KEX_DH_GEX_INIT;
    case SSH_KEX_DH_GEX_REQUEST: return SSH_MSG_KEX_DH_GEX_REQUEST;
    case SSH_USERAUTH_INFO_RESPONSE: return SSH_MSG_USERAUTH_INFO_RESPONSE;
    case SSH_USERAUTH_REQUEST: return SSH_MSG_USERAUTH_REQUEST;
    case SSH_USERAUTH_FAILURE: return SSH_MSG_USERAUTH_FAILURE;
    case SSH_USERAUTH_SUCCESS: return SSH_MSG_USERAUTH_SUCCESS;
    case SSH_USERAUTH_BANNER: return SSH_MSG_USERAUTH_BANNER;
    case SSH_USERAUTH_METHOD_REPLY: return SSH_MSG_USERAUTH_METHOD_REPLY;
    case SSH_GLOBAL_REQUEST: return SSH_MSG_GLOBAL_REQUEST;
    case SSH_REQUEST_SUCCESS: return SSH_MSG_REQUEST_SUCCESS;
    case SSH_REQUEST_FAILURE: return SSH_MSG_REQUEST_FAILURE;
    case SSH_CHANNEL_OPEN: return SSH_MSG_CHANNEL_OPEN;
    case SSH_CHANNEL_OPEN_CONFIRMATION: return SSH_MSG_CHANNEL_OPEN_CONFIRMATION;
    case SSH_CHANNEL_OPEN_FAILURE: return SSH_MSG_CHANNEL_OPEN_FAILURE;
    case SSH_CHANNEL_WINDOW_ADJUST: return SSH_MSG_CHANNEL_WINDOW_ADJUST;
    case SSH_CHANNEL_DATA: return SSH_MSG_CHANNEL_DATA;
    case SSH_CHANNEL_EXTENDED_DATA: return SSH_MSG_CHANNEL_EXTENDED_DATA;
    case SSH_CHANNEL_EOF: return SSH_MSG_CHANNEL_EOF;
    case SSH_CHANNEL_CLOSE: return SSH_MSG_CHANNEL_CLOSE;
    case SSH_CHANNEL_REQUEST: return SSH_MSG_CHANNEL_REQUEST;
    case SSH_CHANNEL_SUCCESS: return SSH_MSG_CHANNEL_SUCCESS;
    case SSH_CHANNEL_FAILURE: return SSH_MSG_CHANNEL_FAILURE;
    default: return 0;
    }
}

static int ssh_is_semantic_type(ssh_packet_type_t type)
{
    /*
     * The PFB-style OpenSSH seed contains an identification banner and a
     * NEWKEYS marker around the clear-text KEX messages.  Mutating either of
     * those markers invalidates the whole transcript before sshd reaches the
     * KEX parser, while the actual client KEX messages remain useful semantic
     * mutation targets.  Keep opaque post-NEWKEYS ciphertext out of this
     * stage as well; it is preserved verbatim by the reassembler and is
     * exercised by the normal havoc stage.
     */
    switch (type) {
    case SSH_OPAQUE:
    case SSH_BANNER:
    case SSH_NEWKEYS:
        return 0;
    default:
        return 1;
    }
}

static uint8_t ssh_packet_code_for_mutation(const ssh_packet_t *p)
{
    if (!p) return 0;
    switch (p->type) {
    case SSH_TRANSPORT_PACKET:
        if (p->u.transport.has_message_code) return p->u.transport.message_code;
        if (p->u.transport.payload_len) return p->u.transport.payload[0];
        return 0;
    case SSH_KEXINIT: return SSH_MSG_KEXINIT;
    case SSH_KEXDH_INIT: return SSH_MSG_KEXDH_INIT;
    case SSH_SERVICE_REQUEST: return SSH_MSG_SERVICE_REQUEST;
    case SSH_NEWKEYS: return SSH_MSG_NEWKEYS;
    default:
        return ssh_default_code_for_type(p->type);
    }
}

static unsigned int ssh_semantic_cutoff(const ssh_packet_t *pkts, unsigned int n)
{
    if (!pkts) return n;
    for (unsigned int i = 0; i < n; ++i)
        if (ssh_packet_code_for_mutation(&pkts[i]) == SSH_MSG_NEWKEYS)
            return i + 1u;
    return n;
}

static void mutate_kexdh_init_payload(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; i < n; ++i) {
        if (pkts[i].type != SSH_KEXDH_INIT) continue;
        ssh_kexdh_init_t *d = &pkts[i].u.kexdh_init;
        d->message_code = SSH_MSG_KEXDH_INIT;
        switch (rand() & 7) {
            case 0: d->e_len = 0; break;
            case 1: d->e_len = 1; d->e[0] = 0; break;
            case 2: if (d->e_len < SSH_MAX_MPINT_BYTES) d->e[d->e_len++] = (unsigned char)rand(); break;
            case 3: if (d->e_len) d->e[rand() % d->e_len] ^= 0xff; break;
            case 4: d->e_len = (uint32_t)(rand() % 257); break;
            default:
                if (d->e_len == 0) d->e_len = 1;
                if (d->e_len > SSH_MAX_MPINT_BYTES) d->e_len = SSH_MAX_MPINT_BYTES;
                for (uint32_t k = 0; k < d->e_len && k < 16; ++k) d->e[k] = (unsigned char)rand();
                break;
        }
        if (d->e_len > SSH_MAX_MPINT_BYTES) d->e_len = SSH_MAX_MPINT_BYTES;
    }
}

static void fill_kexdh_init_profile(ssh_packet_t *pkts, size_t n)
{
    static const uint32_t lens[] = {1, 2, 16, 32, 128, 256, 257};
    for (size_t i = 0; pkts && i < n; ++i) {
        if (pkts[i].type != SSH_KEXDH_INIT) continue;
        ssh_kexdh_init_t *d = &pkts[i].u.kexdh_init;
        d->message_code = SSH_MSG_KEXDH_INIT;
        uint32_t L = lens[rand() % (sizeof(lens) / sizeof(lens[0]))];
        if (L > SSH_MAX_MPINT_BYTES) L = SSH_MAX_MPINT_BYTES;
        d->e_len = L;
        memset(d->e, 0, L);
        if (L == 1) {
            d->e[0] = (uint8_t)(1 + (rand() % 4));
        } else {
            d->e[0] = (uint8_t)(1 + (rand() % 0x7e)); /* positive mpint, no sign padding needed */
            for (uint32_t j = 1; j < L; ++j) d->e[j] = (uint8_t)rand();
            if ((rand() & 7) == 0) d->e[0] = 0; /* explicit positive sign padding path */
        }
    }
}

static void mutate_service_request_payload(ssh_packet_t *pkts, size_t n)
{
    static const char *services[] = {
        "ssh-userauth", "ssh-connection", "ssh-userauth", "ssh-userauth",
        "ssh-bogus", "", "ssh-userauth\x00suffix"
    };
    for (size_t i = 0; i < n; ++i) {
        if (pkts[i].type != SSH_SERVICE_REQUEST) continue;
        ssh_service_request_t *sr = &pkts[i].u.service_request;
        sr->message_code = SSH_MSG_SERVICE_REQUEST;
        const char *v = services[rand() % (sizeof(services)/sizeof(services[0]))];
        size_t len = strlen(v);
        if (len > SSH_MAX_SERVICE_NAME_BYTES) len = SSH_MAX_SERVICE_NAME_BYTES;
        memcpy(sr->service_name, v, len);
        sr->service_name_len = (uint32_t)len;
        if ((rand() & 3) == 0 && sr->service_name_len < SSH_MAX_SERVICE_NAME_BYTES)
            sr->service_name[sr->service_name_len++] = (unsigned char)rand();
    }
}

static void fill_gex_request_profile(ssh_packet_t *pkts, size_t n)
{
    static const uint32_t triples[][3] = {
        {1024, 2048, 8192},
        {2048, 3072, 8192},
        {1024, 1024, 1024},
        {2048, 2048, 2048},
        {8192, 8192, 8192},
        {1, 1024, 2048},
        {4096, 2048, 1024}
    };
    for (size_t i = 0; pkts && i < n; ++i) {
        if (pkts[i].type != SSH_KEX_DH_GEX_REQUEST) continue;
        ssh_typed_payload_t *tp = &pkts[i].u.typed;
        tp->field_schema = SSH_MSG_KEX_DH_GEX_REQUEST;
        tp->message_code = SSH_MSG_KEX_DH_GEX_REQUEST;
        tp->uint32_count = 3;
        size_t idx = (size_t)(rand() % (sizeof(triples) / sizeof(triples[0])));
        tp->uint32_values[0] = triples[idx][0];
        tp->uint32_values[1] = triples[idx][1];
        tp->uint32_values[2] = triples[idx][2];
        tp->string_count = 0;
        tp->trailing_payload.len = 0;
    }
}


static int ssh_kexinit_prefers_gex(const ssh_kexinit_t *k)
{
    static const char gex[] = "diffie-hellman-group-exchange-";
    if (!k) return 0;
    uint32_t n = k->kex_algorithms_len;
    if (n > SSH_MAX_NAMELIST_BYTES) n = SSH_MAX_NAMELIST_BYTES;
    uint32_t glen = (uint32_t)(sizeof(gex) - 1u);
    if (n < glen) return 0;
    return memcmp(k->kex_algorithms, gex, glen) == 0;
}

static void ssh_convert_to_gex_request(ssh_packet_t *p)
{
    if (!p) return;
    memset(&p->u.typed, 0, sizeof(p->u.typed));
    p->type = SSH_KEX_DH_GEX_REQUEST;
    p->wire_len = 0;
    p->has_transport_padding = 0;
    p->transport_padding_length = 0;
    p->transport_payload_length = 0;
    p->u.typed.message_code = SSH_MSG_KEX_DH_GEX_REQUEST;
    p->u.typed.field_schema = SSH_MSG_KEX_DH_GEX_REQUEST;
    p->u.typed.uint32_count = 3;
    p->u.typed.uint32_values[0] = 1024;
    p->u.typed.uint32_values[1] = 2048;
    p->u.typed.uint32_values[2] = 8192;
    fill_gex_request_profile(p, 1);
}

static void ssh_convert_to_kexdh_init(ssh_packet_t *p)
{
    if (!p) return;
    memset(&p->u.kexdh_init, 0, sizeof(p->u.kexdh_init));
    p->type = SSH_KEXDH_INIT;
    p->wire_len = 0;
    p->has_transport_padding = 0;
    p->transport_padding_length = 0;
    p->transport_payload_length = 0;
    p->u.kexdh_init.message_code = SSH_MSG_KEXDH_INIT;
    p->u.kexdh_init.e_len = 1;
    p->u.kexdh_init.e[0] = 1;
    fill_kexdh_init_profile(p, 1);
}

static int ssh_is_client_kex_payload_type(ssh_packet_type_t type)
{
    return type == SSH_KEXDH_INIT ||
           type == SSH_KEX_DH_GEX_REQUEST ||
           type == SSH_KEX_DH_GEX_INIT;
}

static void mutate_newkeys_payload(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; i < n; ++i)
        if (pkts[i].type == SSH_NEWKEYS) pkts[i].u.newkeys.message_code = SSH_MSG_NEWKEYS;
}

static void mutate_typed_message_code(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; i < n; ++i) {
        uint8_t def = ssh_default_code_for_type(pkts[i].type);
        if (!def) continue;
        pkts[i].u.typed.message_code = def;
        pkts[i].u.typed.field_schema = def;
    }
}

static void mutate_typed_payload_len(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_typed_payload_t *tp = &pkts[i].u.typed;
        tp->field_schema = 0;
        switch (rand() & 7) {
            case 0: tp->payload_len = 0; break;
            case 1: tp->payload_len = 1; break;
            case 2: if (tp->payload_len < SSH_MAX_TYPED_PAYLOAD_BYTES) tp->payload_len++; break;
            case 3: if (tp->payload_len) tp->payload_len--; break;
            case 4: tp->payload_len = (uint32_t)(rand() % 256); break;
            default: tp->payload_len = (uint32_t)(rand() % 4096); break;
        }
        if (tp->payload_len > SSH_MAX_TYPED_PAYLOAD_BYTES) tp->payload_len = SSH_MAX_TYPED_PAYLOAD_BYTES;
    }
}

static void mutate_typed_payload(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_typed_payload_t *tp = &pkts[i].u.typed;
        tp->field_schema = 0;
        if (tp->message_code == 0) tp->message_code = ssh_default_code_for_type(pkts[i].type);
        if (tp->payload_len == 0) tp->payload_len = (uint32_t)(1 + (rand() % 32));
        if (tp->payload_len > SSH_MAX_TYPED_PAYLOAD_BYTES) tp->payload_len = SSH_MAX_TYPED_PAYLOAD_BYTES;
        switch (rand() & 7) {
            case 0: memset(tp->payload, 0, tp->payload_len); break;
            case 1: tp->payload[rand() % tp->payload_len] ^= 0xff; break;
            case 2: for (uint32_t k = 0; k < tp->payload_len && k < 64; ++k) tp->payload[k] = (unsigned char)rand(); break;
            case 3: if (tp->payload_len >= 4) { tp->payload[0]=0; tp->payload[1]=0; tp->payload[2]=0; tp->payload[3]=(unsigned char)(rand() & 0xff); } break;
            default: for (uint32_t k = 0; k < tp->payload_len && k < 16; ++k) tp->payload[k] ^= (unsigned char)rand(); break;
        }
    }
}

/* Field-level mutators for the structured RFC 4251 typed SSH payload template. */
static void ssh_prepare_typed(ssh_packet_t *pkt)
{
    if (!pkt) return;
    uint8_t def = ssh_default_code_for_type(pkt->type);
    if (!def) return;
    ssh_typed_payload_t *tp = &pkt->u.typed;
    if (!tp->message_code) tp->message_code = def;
    if (!tp->field_schema) tp->field_schema = tp->message_code;
}

static void mutate_typed_field_schema(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        uint8_t def = ssh_default_code_for_type(pkts[i].type);
        if (!def) continue;
        ssh_prepare_typed(&pkts[i]);
        pkts[i].u.typed.field_schema = def;
        pkts[i].u.typed.message_code = def;
    }
}

static void mutate_typed_boolean_value(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_prepare_typed(&pkts[i]);
        pkts[i].u.typed.boolean_value = (uint8_t)(rand() & 1);
    }
}

static void mutate_typed_uint32_count(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_prepare_typed(&pkts[i]);
        pkts[i].u.typed.uint32_count = (uint8_t)(rand() % (SSH_MAX_TYPED_UINT32_FIELDS + 1));
    }
}

static void mutate_typed_uint32_values(ssh_packet_t *pkts, size_t n)
{
    static const uint32_t vals[] = {
        0, 1, 2, 3, 4, 5, 6, 22, 23, 25, 53, 80, 443, 2222,
        24, 80, 640, 480, 1024, 2048, 4096, 8192, 32768,
        49152, 65535, 65536, 131072, 2097152,
        0xff, 0xffff, 0xffffffffu, 0x7fffffffU
    };
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_prepare_typed(&pkts[i]);
        ssh_typed_payload_t *tp = &pkts[i].u.typed;
        if (tp->uint32_count == 0) tp->uint32_count = 1;
        if (tp->uint32_count > SSH_MAX_TYPED_UINT32_FIELDS) tp->uint32_count = SSH_MAX_TYPED_UINT32_FIELDS;
        for (uint8_t j = 0; j < tp->uint32_count; ++j) {
            if (rand() & 1) tp->uint32_values[j] = vals[rand() % (sizeof(vals) / sizeof(vals[0]))];
            else tp->uint32_values[j] ^= (uint32_t)(1u << (rand() % 31));
        }
    }
}

static void mutate_typed_string_count(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_prepare_typed(&pkts[i]);
        pkts[i].u.typed.string_count = (uint8_t)(rand() % (SSH_MAX_TYPED_STRING_FIELDS + 1));
    }
}

static void ssh_fill_string_field(ssh_string_field_t *s, const char *v)
{
    if (!s || !v) return;
    size_t len = strlen(v);
    if (len > SSH_MAX_TYPED_FIELD_BYTES) len = SSH_MAX_TYPED_FIELD_BYTES;
    s->len = (uint32_t)len;
    memset(s->bytes, 0, sizeof(s->bytes));
    memcpy(s->bytes, v, len);
}


static void ssh_fill_typed_semantic_profile(ssh_packet_t *p)
{
    if (!p || !ssh_default_code_for_type(p->type)) return;
    ssh_prepare_typed(p);
    ssh_typed_payload_t *tp = &p->u.typed;
    static const char *users[] = {"root", "admin", "test", "ubuntu", "user", "git", "nobody", "lemur", "keyi", "oracle", "postgres", "www-data", "invalid"};
    static const char *passwords[] = {"", "password", "root", "admin", "123456", "toor", "test", "ubuntu", "changeme", "letmein", "P@ssw0rd", "invalid"};
    static const char *pubkey_algs[] = {"ssh-rsa", "rsa-sha2-256", "rsa-sha2-512", "ssh-ed25519", "ecdsa-sha2-nistp256", "sk-ssh-ed25519@openssh.com"};
    static const char *commands[] = {"id", "whoami", "uname -a", "pwd", "true", "false", "ls", "ls -la /tmp", "echo lemur", "printf test", "cat /etc/hostname", "exit 0"};
    static const char *terms[] = {"xterm", "xterm-256color", "vt100", "linux", "ansi", "dumb"};
    static const char *hosts[] = {"127.0.0.1", "localhost", "0.0.0.0", "::1", "192.0.2.1", "example.com"};
    static const uint32_t ports[] = {0, 1, 22, 80, 443, 2222, 8022, 8080, 65535};
    tp->field_schema = ssh_default_code_for_type(p->type);
    tp->message_code = ssh_default_code_for_type(p->type);
    tp->trailing_payload.len = 0;
    switch (p->type) {
    case SSH_SERVICE_ACCEPT:
        tp->string_count = 1;
        ssh_fill_string_field(&tp->strings[0], (rand() & 1) ? "ssh-userauth" : "ssh-connection");
        break;
    case SSH_USERAUTH_REQUEST:
        tp->string_count = 3;
        ssh_fill_string_field(&tp->strings[0], users[rand() % (sizeof(users) / sizeof(users[0]))]);
        ssh_fill_string_field(&tp->strings[1], "ssh-connection");
        tp->boolean_count = 0;
        tp->boolean_value = 0;
        switch (rand() % 6) {
        case 0:
            ssh_fill_string_field(&tp->strings[2], "none");
            break;
        case 1:
        case 2:
            ssh_fill_string_field(&tp->strings[2], "password");
            tp->boolean_count = 1;
            tp->boolean_values[0] = 0;
            tp->boolean_value = 0;
            tp->string_count = 4;
            ssh_fill_string_field(&tp->strings[3], passwords[rand() % (sizeof(passwords) / sizeof(passwords[0]))]);
            break;
        case 3:
            ssh_fill_string_field(&tp->strings[2], "publickey");
            tp->boolean_count = 1;
            tp->boolean_values[0] = 0;
            tp->boolean_value = 0;
            tp->string_count = 5;
            ssh_fill_string_field(&tp->strings[3], pubkey_algs[rand() % (sizeof(pubkey_algs) / sizeof(pubkey_algs[0]))]);
            ssh_fill_string_field(&tp->strings[4], "AAAAB3NzaC1yc2EAAAADAQABAAABAQC7");
            break;
        case 4:
            ssh_fill_string_field(&tp->strings[2], "hostbased");
            tp->string_count = 6;
            ssh_fill_string_field(&tp->strings[3], pubkey_algs[rand() % (sizeof(pubkey_algs) / sizeof(pubkey_algs[0]))]);
            ssh_fill_string_field(&tp->strings[4], "AAAAB3NzaC1yc2EAAAADAQABAAABAQC7");
            ssh_fill_string_field(&tp->strings[5], hosts[rand() % (sizeof(hosts) / sizeof(hosts[0]))]);
            break;
        default:
            ssh_fill_string_field(&tp->strings[2], "keyboard-interactive");
            tp->string_count = 5;
            ssh_fill_string_field(&tp->strings[3], "");
            ssh_fill_string_field(&tp->strings[4], (rand() & 1) ? "" : "pam");
            break;
        }
        break;
    case SSH_USERAUTH_FAILURE:
        tp->string_count = 1;
        ssh_fill_string_field(&tp->strings[0], "publickey,password,keyboard-interactive");
        tp->boolean_count = 1; tp->boolean_values[0] = 0;
        break;
    case SSH_GLOBAL_REQUEST:
        tp->string_count = 2;
        static const char *global_reqs[] = {"tcpip-forward", "cancel-tcpip-forward", "keepalive@openssh.com", "hostkeys-00@openssh.com", "no-more-sessions@openssh.com"};
        ssh_fill_string_field(&tp->strings[0], global_reqs[rand() % (sizeof(global_reqs) / sizeof(global_reqs[0]))]);
        ssh_fill_string_field(&tp->strings[1], hosts[rand() % (sizeof(hosts) / sizeof(hosts[0]))]);
        tp->uint32_count = 1;
        tp->uint32_values[0] = ports[rand() % (sizeof(ports) / sizeof(ports[0]))];
        tp->boolean_count = 1; tp->boolean_values[0] = 0; tp->boolean_value = 0;
        break;
    case SSH_CHANNEL_OPEN:
        if ((rand() % 4) == 0) {
            tp->string_count = 3;
            ssh_fill_string_field(&tp->strings[0], "direct-tcpip");
            ssh_fill_string_field(&tp->strings[1], hosts[rand() % (sizeof(hosts) / sizeof(hosts[0]))]);
            ssh_fill_string_field(&tp->strings[2], "127.0.0.1");
            tp->uint32_count = 5;
            tp->uint32_values[3] = ports[rand() % (sizeof(ports) / sizeof(ports[0]))];
            tp->uint32_values[4] = 49152u + (uint32_t)(rand() % 1024);
        } else {
            tp->string_count = 1;
            ssh_fill_string_field(&tp->strings[0], "session");
            tp->uint32_count = 3;
        }
        tp->uint32_values[0] = (uint32_t)(rand() & 0xffff);
        tp->uint32_values[1] = 0x200000;
        tp->uint32_values[2] = 0x8000;
        break;
    case SSH_CHANNEL_REQUEST:
        tp->string_count = 1;
        tp->uint32_count = 1;
        tp->uint32_values[0] = 0;
        switch (rand() % 10) {
        case 0:
            ssh_fill_string_field(&tp->strings[0], "shell");
            break;
        case 1:
        case 2:
            ssh_fill_string_field(&tp->strings[0], "exec");
            tp->string_count = 2;
            ssh_fill_string_field(&tp->strings[1], commands[rand() % (sizeof(commands) / sizeof(commands[0]))]);
            break;
        case 3:
            ssh_fill_string_field(&tp->strings[0], "pty-req");
            tp->string_count = 3;
            ssh_fill_string_field(&tp->strings[1], terms[rand() % (sizeof(terms) / sizeof(terms[0]))]);
            ssh_fill_string_field(&tp->strings[2], "");
            tp->uint32_count = 5;
            tp->uint32_values[1] = 80;
            tp->uint32_values[2] = 24;
            tp->uint32_values[3] = 640;
            tp->uint32_values[4] = 480;
            break;
        case 4:
            ssh_fill_string_field(&tp->strings[0], "subsystem");
            tp->string_count = 2;
            ssh_fill_string_field(&tp->strings[1], "sftp");
            break;
        case 5:
            ssh_fill_string_field(&tp->strings[0], "window-change");
            tp->uint32_count = 5;
            tp->uint32_values[1] = (rand() & 1) ? 80 : 132;
            tp->uint32_values[2] = (rand() & 1) ? 24 : 43;
            tp->uint32_values[3] = (rand() & 1) ? 640 : 1024;
            tp->uint32_values[4] = (rand() & 1) ? 480 : 768;
            break;
        case 6:
            ssh_fill_string_field(&tp->strings[0], "xon-xoff");
            tp->boolean_count = 2;
            tp->boolean_values[1] = (uint8_t)(rand() & 1);
            break;
        case 7:
            ssh_fill_string_field(&tp->strings[0], "signal");
            tp->string_count = 2;
            ssh_fill_string_field(&tp->strings[1], (rand() & 1) ? "TERM" : "KILL");
            break;
        case 8:
            ssh_fill_string_field(&tp->strings[0], "exit-status");
            tp->uint32_count = 2;
            tp->uint32_values[1] = (uint32_t)(rand() % 256);
            break;
        default:
            ssh_fill_string_field(&tp->strings[0], "env");
            tp->string_count = 3;
            ssh_fill_string_field(&tp->strings[1], (rand() & 1) ? "LANG" : "LC_ALL");
            ssh_fill_string_field(&tp->strings[2], (rand() & 1) ? "C" : "en_US.UTF-8");
            break;
        }
        tp->boolean_count = 1; tp->boolean_values[0] = 0; tp->boolean_value = 0;
        break;
    case SSH_CHANNEL_DATA:
    case SSH_CHANNEL_EXTENDED_DATA:
        tp->uint32_count = (p->type == SSH_CHANNEL_EXTENDED_DATA) ? 2 : 1;
        tp->uint32_values[0] = 0;
        if (p->type == SSH_CHANNEL_EXTENDED_DATA) tp->uint32_values[1] = 1;
        tp->string_count = 1;
        ssh_fill_string_field(&tp->strings[0], commands[rand() % (sizeof(commands) / sizeof(commands[0]))]);
        break;
    default:
        if (tp->string_count == 0) {
            tp->string_count = 1;
            ssh_fill_string_field(&tp->strings[0], (p->type == SSH_DEBUG) ? "lemur" : "ssh-connection");
        }
        break;
    }
}

static void add_typed_strings(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_prepare_typed(&pkts[i]);
        ssh_typed_payload_t *tp = &pkts[i].u.typed;
        if (tp->string_count == 0 || pkts[i].type == SSH_USERAUTH_REQUEST ||
            pkts[i].type == SSH_CHANNEL_OPEN || pkts[i].type == SSH_CHANNEL_REQUEST ||
            pkts[i].type == SSH_GLOBAL_REQUEST || pkts[i].type == SSH_SERVICE_ACCEPT) {
            ssh_fill_typed_semantic_profile(&pkts[i]);
            continue;
        }
        static const char *fallback_vals[] = {"ssh-userauth", "ssh-connection", "session", "publickey", "password"};
        if (tp->string_count < SSH_MAX_TYPED_STRING_FIELDS) {
            ssh_fill_string_field(&tp->strings[tp->string_count], fallback_vals[rand() % (sizeof(fallback_vals) / sizeof(fallback_vals[0]))]);
            tp->string_count++;
        }
    }
}

static void delete_typed_strings(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        if (pkts[i].u.typed.string_count) pkts[i].u.typed.string_count--;
    }
}

static void repeat_typed_strings(ssh_packet_t *pkts, size_t n)
{
    add_typed_strings(pkts, n);
    add_typed_strings(pkts, n);
}

static void mutate_typed_strings(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_prepare_typed(&pkts[i]);
        ssh_typed_payload_t *tp = &pkts[i].u.typed;
        if (tp->string_count == 0) add_typed_strings(pkts + i, 1);
        if (tp->string_count == 0) continue;
        uint8_t idx = (uint8_t)(rand() % tp->string_count);
        ssh_string_field_t *sf = &tp->strings[idx];
        if (sf->len == 0) ssh_fill_string_field(sf, "ssh-userauth");
        if (sf->len > SSH_MAX_TYPED_FIELD_BYTES) sf->len = SSH_MAX_TYPED_FIELD_BYTES;
        if ((pkts[i].type == SSH_USERAUTH_REQUEST || pkts[i].type == SSH_CHANNEL_REQUEST ||
             pkts[i].type == SSH_CHANNEL_OPEN || pkts[i].type == SSH_GLOBAL_REQUEST) &&
            (rand() % 4) != 0) {
            ssh_fill_typed_semantic_profile(&pkts[i]);
            continue;
        }
        switch (rand() & 3) {
            case 0: sf->bytes[0] ^= 0xff; break;
            case 1: if (sf->len < SSH_MAX_TYPED_FIELD_BYTES) sf->bytes[sf->len++] = (unsigned char)('A' + (rand() % 26)); break;
            case 2: sf->len = (uint32_t)(rand() % 64); break;
            default: for (uint32_t k = 0; k < sf->len && k < 16; ++k) sf->bytes[k] = (unsigned char)rand(); break;
        }
    }
}

static void add_typed_trailing_payload(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_prepare_typed(&pkts[i]);
        ssh_string_field_t *tail = &pkts[i].u.typed.trailing_payload;
        if (tail->len == 0) tail->len = 4;
        if (tail->len > SSH_MAX_TYPED_FIELD_BYTES) tail->len = SSH_MAX_TYPED_FIELD_BYTES;
        for (uint32_t k = 0; k < tail->len && k < 32; ++k) tail->bytes[k] = (unsigned char)rand();
    }
}

static void delete_typed_trailing_payload(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) if (ssh_default_code_for_type(pkts[i].type)) pkts[i].u.typed.trailing_payload.len = 0;
}

static void repeat_typed_trailing_payload(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_string_field_t *tail = &pkts[i].u.typed.trailing_payload;
        if (tail->len == 0) add_typed_trailing_payload(pkts + i, 1);
        uint32_t old = tail->len;
        if (old && old * 2 <= SSH_MAX_TYPED_FIELD_BYTES) {
            memcpy(tail->bytes + old, tail->bytes, old);
            tail->len = old * 2;
        }
    }
}

static void mutate_typed_trailing_payload(ssh_packet_t *pkts, size_t n)
{
    for (size_t i = 0; pkts && i < n; ++i) {
        if (!ssh_default_code_for_type(pkts[i].type)) continue;
        ssh_string_field_t *tail = &pkts[i].u.typed.trailing_payload;
        if (tail->len == 0) add_typed_trailing_payload(pkts + i, 1);
        if (tail->len == 0) continue;
        if (tail->len > SSH_MAX_TYPED_FIELD_BYTES) tail->len = SSH_MAX_TYPED_FIELD_BYTES;
        switch (rand() & 3) {
            case 0: tail->bytes[rand() % tail->len] ^= 0xff; break;
            case 1: if (tail->len < SSH_MAX_TYPED_FIELD_BYTES) tail->bytes[tail->len++] = (unsigned char)rand(); break;
            case 2: tail->len = (uint32_t)(rand() % 128); break;
            default: for (uint32_t k = 0; k < tail->len && k < 32; ++k) tail->bytes[k] ^= (unsigned char)rand(); break;
        }
    }
}

void dispatch_ssh_mutation(ssh_packet_t *pkts, unsigned int pkt_count)
{
    static unsigned int selector;
    if (!pkts || pkt_count == 0)
        return;

    ssh_packet_t *p = NULL;
    unsigned int cutoff = ssh_semantic_cutoff(pkts, pkt_count);
    if (cutoff == 0 || cutoff > pkt_count)
        cutoff = pkt_count;
    for (unsigned int a = 0; a < cutoff; ++a)
    {
        ssh_packet_t *cand = &pkts[(selector + a) % cutoff];
        if (ssh_is_semantic_type(cand->type))
        {
            p = cand;
            break;
        }
    }
    selector++;
    if (!p)
        return;
    p->wire_len = 0;

    switch (p->type)
    {
    case SSH_BANNER:
        switch (selector % 6)
        {
        case 0: mutate_software(p, 1); break;
        case 1: mutate_software_len(p, 1); break;
        case 2: add_comments(p, 1); break;
        case 3: mutate_comments(p, 1); break;
        case 4: mutate_comments_len(p, 1); break;
        default: delete_comments(p, 1); break;
        }
        break;
    case SSH_TRANSPORT_PACKET:
        switch (selector % 11)
        {
        case 0: mutate_packet_length(p, 1); break;
        case 1: mutate_padding_length(p, 1); break;
        case 2: mutate_payload_len(p, 1); break;
        case 3: mutate_payload(p, 1); break;
        case 4: mutate_padding(p, 1); break;
        case 5: mutate_message_code(p, 1); break;
        case 6: add_has_message_code(p, 1); break;
        case 7: delete_has_message_code(p, 1); break;
        case 8: mutate_has_message_code(p, 1); break;
        case 9: add_message_code(p, 1); break;
        default: delete_message_code(p, 1); break;
        }
        break;
    case SSH_KEXINIT:
        switch (selector % 50)
        {
        case 0:
        case 1:
        case 2:
        case 3:
        case 4:
        case 5:
        case 6:
        case 7: set_kexinit_profile(&p->u.kexinit, selector); break;
        case 8: mutate_cookie(p, 1); break;
        case 9: add_kex_algorithms(p, 1); break;
        case 10: mutate_kex_algorithms(p, 1); break;
        case 11: mutate_kex_algorithms_len(p, 1); break;
        case 12: add_server_host_key_algorithms(p, 1); break;
        case 13: mutate_server_host_key_algorithms(p, 1); break;
        case 14: mutate_server_host_key_algorithms_len(p, 1); break;
        case 15: add_encryption_algorithms_client_to_server(p, 1); break;
        case 16: mutate_encryption_algorithms_client_to_server(p, 1); break;
        case 17: mutate_encryption_algorithms_client_to_server_len(p, 1); break;
        case 18: add_encryption_algorithms_server_to_client(p, 1); break;
        case 19: mutate_encryption_algorithms_server_to_client(p, 1); break;
        case 20: mutate_encryption_algorithms_server_to_client_len(p, 1); break;
        case 21: add_mac_algorithms_client_to_server(p, 1); break;
        case 22: mutate_mac_algorithms_client_to_server(p, 1); break;
        case 23: mutate_mac_algorithms_client_to_server_len(p, 1); break;
        case 24: add_mac_algorithms_server_to_client(p, 1); break;
        case 25: mutate_mac_algorithms_server_to_client(p, 1); break;
        case 26: mutate_mac_algorithms_server_to_client_len(p, 1); break;
        case 27: add_compression_algorithms_client_to_server(p, 1); break;
        case 28: mutate_compression_algorithms_client_to_server(p, 1); break;
        case 29: mutate_compression_algorithms_client_to_server_len(p, 1); break;
        case 30: add_compression_algorithms_server_to_client(p, 1); break;
        case 31: mutate_compression_algorithms_server_to_client(p, 1); break;
        case 32: mutate_compression_algorithms_server_to_client_len(p, 1); break;
        case 33: add_languages_client_to_server(p, 1); break;
        case 34: delete_languages_client_to_server(p, 1); break;
        case 35: mutate_languages_client_to_server(p, 1); break;
        case 36: mutate_languages_client_to_server_len(p, 1); break;
        case 37: add_languages_server_to_client(p, 1); break;
        case 38: delete_languages_server_to_client(p, 1); break;
        case 39: mutate_languages_server_to_client(p, 1); break;
        case 40: mutate_languages_server_to_client_len(p, 1); break;
        case 41: delete_kex_algorithms(p, 1); break;
        case 42: delete_server_host_key_algorithms(p, 1); break;
        case 43: delete_encryption_algorithms_client_to_server(p, 1); break;
        case 44: delete_encryption_algorithms_server_to_client(p, 1); break;
        case 45: delete_mac_algorithms_client_to_server(p, 1); break;
        case 46: delete_mac_algorithms_server_to_client(p, 1); break;
        case 47: delete_compression_algorithms_client_to_server(p, 1); break;
        case 48: delete_compression_algorithms_server_to_client(p, 1); break;
        default: mutate_first_kex_packet_follows(p, 1); break;
        }
        break;
    case SSH_KEXDH_INIT:
        if ((selector & 3) == 0) mutate_kexdh_init_payload(p, 1);
        else fill_kexdh_init_profile(p, 1);
        break;
    case SSH_SERVICE_REQUEST:
        mutate_service_request_payload(p, 1);
        break;
    case SSH_NEWKEYS:
        mutate_newkeys_payload(p, 1);
        break;
    default:
        switch (p->type)
        {
        case SSH_DISCONNECT:
            switch (selector % 7) {
            case 0: mutate_typed_uint32_values(p, 1); break;
            case 1: mutate_typed_strings(p, 1); break;
            case 2: add_typed_strings(p, 1); break;
            case 3: delete_typed_strings(p, 1); break;
            case 4: repeat_typed_strings(p, 1); break;
            case 5: mutate_typed_string_count(p, 1); break;
            default: mutate_typed_uint32_count(p, 1); break;
            }
            break;
        case SSH_IGNORE:
        case SSH_SERVICE_ACCEPT:
        case SSH_USERAUTH_BANNER:
        case SSH_USERAUTH_METHOD_REPLY:
            switch (selector % 5) {
            case 0: mutate_typed_strings(p, 1); break;
            case 1: add_typed_strings(p, 1); break;
            case 2: delete_typed_strings(p, 1); break;
            case 3: repeat_typed_strings(p, 1); break;
            default: mutate_typed_string_count(p, 1); break;
            }
            break;
        case SSH_UNIMPLEMENTED:
        case SSH_CHANNEL_WINDOW_ADJUST:
        case SSH_CHANNEL_EOF:
        case SSH_CHANNEL_CLOSE:
        case SSH_CHANNEL_SUCCESS:
        case SSH_CHANNEL_FAILURE:
            switch (selector % 2) {
            case 0: mutate_typed_uint32_values(p, 1); break;
            default: mutate_typed_uint32_count(p, 1); break;
            }
            break;
        case SSH_DEBUG:
        case SSH_USERAUTH_FAILURE:
        case SSH_GLOBAL_REQUEST:
            switch (selector % 8) {
            case 0: mutate_typed_boolean_value(p, 1); break;
            case 1: mutate_typed_strings(p, 1); break;
            case 2: add_typed_strings(p, 1); break;
            case 3: delete_typed_strings(p, 1); break;
            case 4: repeat_typed_strings(p, 1); break;
            case 5: mutate_typed_string_count(p, 1); break;
            case 6: add_typed_trailing_payload(p, 1); break;
            default: mutate_typed_trailing_payload(p, 1); break;
            }
            break;
        case SSH_KEXDH_REPLY:
        case SSH_CHANNEL_OPEN_FAILURE:
        case SSH_KEX_DH_GEX_REQUEST:
            switch (selector % 8) {
            case 0: if (p->type == SSH_KEX_DH_GEX_REQUEST) fill_gex_request_profile(p, 1); else mutate_typed_strings(p, 1); break;
            case 1: if (p->type == SSH_KEX_DH_GEX_REQUEST) fill_gex_request_profile(p, 1); else add_typed_strings(p, 1); break;
            case 2: if (p->type == SSH_KEX_DH_GEX_REQUEST) fill_gex_request_profile(p, 1); else delete_typed_strings(p, 1); break;
            case 3: if (p->type == SSH_KEX_DH_GEX_REQUEST) fill_gex_request_profile(p, 1); else repeat_typed_strings(p, 1); break;
            case 4: if (p->type == SSH_KEX_DH_GEX_REQUEST) fill_gex_request_profile(p, 1); else mutate_typed_string_count(p, 1); break;
            case 5: mutate_typed_uint32_values(p, 1); break;
            case 6: mutate_typed_uint32_count(p, 1); break;
            default: mutate_typed_trailing_payload(p, 1); break;
            }
            break;
        case SSH_USERAUTH_REQUEST:
            switch (selector % 12) {
            case 0:
            case 1:
            case 2:
            case 3: ssh_fill_typed_semantic_profile(p); break;
            case 4: mutate_typed_boolean_value(p, 1); break;
            case 5: mutate_typed_strings(p, 1); break;
            case 6: add_typed_strings(p, 1); break;
            case 7: mutate_typed_string_count(p, 1); break;
            case 8: add_typed_trailing_payload(p, 1); break;
            case 9: delete_typed_trailing_payload(p, 1); break;
            case 10: mutate_typed_trailing_payload(p, 1); break;
            default: mutate_typed_payload(p, 1); break;
            }
            break;
        case SSH_CHANNEL_OPEN:
        case SSH_CHANNEL_OPEN_CONFIRMATION:
            switch (selector % 7) {
            case 0:
            case 1:
            case 2: ssh_fill_typed_semantic_profile(p); break;
            case 3: mutate_typed_strings(p, 1); break;
            case 4: mutate_typed_uint32_values(p, 1); break;
            case 5: add_typed_trailing_payload(p, 1); break;
            default: mutate_typed_trailing_payload(p, 1); break;
            }
            break;
        case SSH_CHANNEL_DATA:
        case SSH_CHANNEL_EXTENDED_DATA:
        case SSH_CHANNEL_REQUEST:
            switch (selector % 12) {
            case 0:
            case 1:
            case 2:
            case 3: ssh_fill_typed_semantic_profile(p); break;
            case 4: mutate_typed_boolean_value(p, 1); break;
            case 5: mutate_typed_strings(p, 1); break;
            case 6: add_typed_strings(p, 1); break;
            case 7: mutate_typed_uint32_values(p, 1); break;
            case 8: mutate_typed_uint32_count(p, 1); break;
            case 9: add_typed_trailing_payload(p, 1); break;
            case 10: delete_typed_trailing_payload(p, 1); break;
            default: mutate_typed_trailing_payload(p, 1); break;
            }
            break;
        case SSH_REQUEST_SUCCESS:
            switch (selector % 4) {
            case 0: add_typed_trailing_payload(p, 1); break;
            case 1: delete_typed_trailing_payload(p, 1); break;
            case 2: repeat_typed_trailing_payload(p, 1); break;
            default: mutate_typed_trailing_payload(p, 1); break;
            }
            break;
        case SSH_USERAUTH_SUCCESS:
        case SSH_REQUEST_FAILURE:
            break;
        default:
            mutate_typed_payload(p, 1);
            break;
        }
        break;
    }
}

static int ssh_mutator_is_server_to_client(ssh_packet_type_t type)
{
    switch (type) {
    case SSH_SERVICE_ACCEPT:
    case SSH_KEXDH_REPLY:
    case SSH_USERAUTH_FAILURE:
    case SSH_USERAUTH_SUCCESS:
    case SSH_USERAUTH_BANNER:
    case SSH_USERAUTH_METHOD_REPLY:
    case SSH_REQUEST_SUCCESS:
    case SSH_REQUEST_FAILURE:
    case SSH_CHANNEL_OPEN_CONFIRMATION:
    case SSH_CHANNEL_OPEN_FAILURE:
    case SSH_CHANNEL_SUCCESS:
    case SSH_CHANNEL_FAILURE:
        return 1;
    default:
        return 0;
    }
}

static int ssh_mutator_is_channel_client_msg(ssh_packet_type_t type)
{
    return type == SSH_CHANNEL_OPEN ||
           type == SSH_CHANNEL_WINDOW_ADJUST ||
           type == SSH_CHANNEL_DATA ||
           type == SSH_CHANNEL_EXTENDED_DATA ||
           type == SSH_CHANNEL_EOF ||
           type == SSH_CHANNEL_CLOSE ||
           type == SSH_CHANNEL_REQUEST;
}

static void ssh_mutator_drop_packet(ssh_packet_t *p)
{
    if (!p) return;
    p->type = SSH_OPAQUE;
    p->wire_len = 0;
    p->has_transport_padding = 0;
    p->transport_padding_length = 0;
    p->transport_payload_length = 0;
    memset(&p->u.opaque, 0, sizeof(p->u.opaque));
}

static void ssh_apply_sequence_profile(ssh_packet_t *pkts, unsigned int pkt_count)
{
    if (!pkts || pkt_count <= 1) return;
    unsigned int cutoff = ssh_semantic_cutoff(pkts, pkt_count);
    int saw_kexinit = 0;
    int kex_requires_gex_request = 0;
    int saw_kex_payload = 0;
    int saw_service = 0;
    int saw_userauth = 0;
    int saw_channel_open = 0;
    uint32_t channel_id = 0;

    for (unsigned int i = 0; i < pkt_count; ++i) {
        uint8_t code = ssh_packet_code_for_mutation(&pkts[i]);
        if (i >= cutoff) {
            /* Preserve post-NEWKEYS opaque ciphertext from real seeds; it is
             * often the only way to exercise encrypted auth/channel handling
             * without implementing SSH key derivation in the mutator. */
            if (pkts[i].type != SSH_OPAQUE)
                ssh_mutator_drop_packet(&pkts[i]);
            continue;
        }
        if (ssh_mutator_is_server_to_client(pkts[i].type)) {
            ssh_mutator_drop_packet(&pkts[i]);
            continue;
        }
        if (pkts[i].type == SSH_KEXINIT) {
            saw_kexinit = 1;
            kex_requires_gex_request = ssh_kexinit_prefers_gex(&pkts[i].u.kexinit);
        } else if (pkts[i].type != SSH_TRANSPORT_PACKET &&
                   (code == SSH_MSG_KEXDH_INIT || code == SSH_MSG_KEX_DH_GEX_INIT ||
                    code == SSH_MSG_KEX_DH_GEX_REQUEST) && !saw_kexinit) {
            ssh_mutator_drop_packet(&pkts[i]);
            continue;
        } else if (pkts[i].type != SSH_TRANSPORT_PACKET && ssh_is_client_kex_payload_type(pkts[i].type)) {
            if (!saw_kex_payload) {
                if (kex_requires_gex_request)
                    ssh_convert_to_gex_request(&pkts[i]);
                else if (pkts[i].type != SSH_KEXDH_INIT)
                    ssh_convert_to_kexdh_init(&pkts[i]);
                saw_kex_payload = 1;
            } else {
                ssh_mutator_drop_packet(&pkts[i]);
                continue;
            }
        } else if (pkts[i].type == SSH_SERVICE_REQUEST) {
            mutate_service_request_payload(&pkts[i], 1);
            memcpy(pkts[i].u.service_request.service_name, "ssh-userauth", 12);
            pkts[i].u.service_request.service_name_len = 12;
            saw_service = 1;
        } else if (pkts[i].type == SSH_USERAUTH_REQUEST) {
            ssh_fill_typed_semantic_profile(&pkts[i]);
            if (!saw_service && (rand() & 1)) {
                ssh_fill_string_field(&pkts[i].u.typed.strings[2], "none");
                pkts[i].u.typed.string_count = 3;
                pkts[i].u.typed.boolean_count = 0;
                pkts[i].u.typed.boolean_value = 0;
            }
            saw_userauth = 1;
        } else if (ssh_mutator_is_channel_client_msg(pkts[i].type)) {
            if (!saw_userauth) {
                ssh_mutator_drop_packet(&pkts[i]);
                continue;
            }
            if (pkts[i].type == SSH_CHANNEL_OPEN) {
                ssh_fill_typed_semantic_profile(&pkts[i]);
                if (pkts[i].u.typed.uint32_count < 3)
                    pkts[i].u.typed.uint32_count = 3;
                channel_id = pkts[i].u.typed.uint32_values[0];
                saw_channel_open = 1;
            } else if (!saw_channel_open) {
                ssh_mutator_drop_packet(&pkts[i]);
                continue;
            } else {
                if (pkts[i].type == SSH_CHANNEL_REQUEST ||
                    pkts[i].type == SSH_CHANNEL_DATA ||
                    pkts[i].type == SSH_CHANNEL_EXTENDED_DATA)
                    ssh_fill_typed_semantic_profile(&pkts[i]);
                if (pkts[i].u.typed.uint32_count < 1)
                    pkts[i].u.typed.uint32_count = 1;
                pkts[i].u.typed.uint32_values[0] = channel_id;
            }
        }
    }
}

void dispatch_ssh_multiple_mutations(ssh_packet_t *pkts, unsigned int pkt_count,
                                     unsigned int rounds)
{
    if (!pkts || pkt_count == 0)
        return;
    if (rounds == 0)
        rounds = 1;
    for (unsigned int i = 0; i < rounds; ++i)
    {
        dispatch_ssh_mutation(pkts, pkt_count);
    }
    ssh_apply_sequence_profile(pkts, pkt_count);

    /* Keep this invariant even when FIXER_OFF=1.  The semantic-only and
     * no-fixer ablations must still produce inputs that use the plaintext
     * replay protocol; otherwise the seed's original encrypted proposals can
     * reappear whenever the selected semantic operation touches another
     * packet. */
    for (unsigned int i = 0; i < pkt_count; ++i) {
        if (pkts[i].type == SSH_KEXINIT)
            set_plaintext_algorithms(&pkts[i].u.kexinit);
    }
}

// reserved_zero (Fixed = must be 0)
// not mutable and stop. Do not generate any mutator functions.
